<span class="line"><span style="--shiki-light:#986801;--shiki-dark:#D19A66;">  --classname</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> com.example.InventoryService</span><span style="--shiki-light:#986801;--shiki-dark:#D19A66;"> --methodname</span><span style="--shiki-light:#50A14F;--shiki-dark:#98C379;"> checkStock</span><span style="--shiki-light:#0184BC;--shiki-dark:#56B6C2;"> \\</span></span>
